,.controls-card,.setlist-card{background:linear-gradient(145deg,#1c1b18,#151513);border:1px solid #ffffff12;border-radius:5px}.song-card{padding:10px}.album-art{height:170px;position:relative;overflow:hidden;background:linear-gradient(155deg,#30372d,#aa7546 70%,#dfb15d);border-radius:3px}.moon{position:absolute;width:37px;height:37px;border-radius:50%;background:#f1d89c;top:21px;right:26px;box-shadow:0 0 30px #f4d79688}.hill{position:absolute;bottom:-16px;border-radius:50% 50% 0 0}.hill-back{height:86px;width:210px;left:-42px;background:#374238;transform:rotate(-9deg)}.hill-front{height:70px;width:240px;right:-74px;background:#222f29;transform:rotate(7deg)}.art-banjo{position:absolute;width:68px;height:68px;border:6px solid #dfb86c;background:#d2a35a;border-radius:50%;top:58px;left:71px;box-shadow:inset 0 0 0 3px #553c2b;transform:rotate(-28deg)}.art-banjo:before{content:'';position:absolute;width:11px;height:87px;background:linear-gradient(90deg,#65442b,#a17848,#50351f);left:25px;top:-67px;border:1px solid #ddbd77}.art-banjo i{position:absolute;width:1px;height:61px;background:#fff2c6;left:24px;top:-37px;box-shadow:4px 0 #fff2c699,-4px 0 #fff2c699}.art-spark{position:absolute;top:33px;left:37px;color:#ffdd8e;font-size:18px}.art-caption{position:absolute;left:13px;bottom:10px;color:#e3c88e;font:9px/1.5 'DM Mono';letter-spacing:1.4px}.art-caption b{color:#fff2ce;font-size:12px}.song-meta{padding:14px 5px 10px}.song-meta h2{font:700 19px/1.13 'Playfair Display',serif;margin:8px 0}.song-meta p{font:9px 'DM Mono';color:#aaa392;letter-spacing:1px;margin:0}.song-tags{display:flex;gap:6px;padding:0 5px 6px}.song-tags span{font-size:8px;padding:6px 7px;background:#27251f;color:#c1b69d;border-radius:2px}.tip-card{display:flex;gap:10px;padding:14px 12px;color:#aaa598}.tip-icon{font-size:18px;color:var(--gold);padding-top:2px}.tip-card p{font-size:10px;line-height:1.65;margin:0}.tip-card strong{font-size:8px;color:#e1c47f;display:inline-block;margin-bottom:4px}.stage-wrap{min-width:0}.stage-topline{height:36px;display:flex;align-items:flex-start;justify-content:space-between}.stage-kicker{color:#928d80;font-size:9px;margin-right:10px}.stage-name{font:700 13px 'Playfair Display',serif}.difficulty{display:flex;align-items:center;gap:3px;color:var(--gold);font-size:9px}.difficulty .dim{color:#46433b}.difficulty small{margin-left:7px;color:#a9a293;font-size:8px}.stage-frame{height:520px;position:relative;overflow:hidden;border:1px solid #76623b66;border-radius:4px;background:#111412;box-shadow:0 15px 55px #0008,inset 0 0 50px #000}.stage-frame canvas{position:absolute;inset:0;width:100%;height:100%;display:block}.canvas-vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(90deg,#07080776,transparent 11%,transparent 89%,#07080776),linear-gradient(0deg,#090a08bb,transparent 19%,transparent 70%,#090a0880)}.game-overlay{position:absolute;inset:0;display:grid;place-items:center;text-align:center;background:radial-gradient(ellipse at center,#11130fcc,#0a0c0bcc 75%);transition:opacity .25s}.game-overlay.hidden{opacity:0;pointer-events:none}.overlay-content{margin-top:-4px}.banjo-emblem{width:48px;height:48px;margin:0 auto 13px;border:1px solid #e8bb5c88;border-radius:50%;display:grid;place-items:center;color:var(--gold);font-size:22px;background:#c08c321a;box-shadow:0 0 32px #dea63d19}.overlay-eyebrow{font:9px 'DM Mono';letter-spacing:2px;color:#c0a55d;margin:0 0 8px}.overlay-content h2{font:800 34px/1.05 'Playfair Display',serif;margin:0 0 12px}.overlay-copy{font-size:11px;line-height:1.6;color:#aaa79c;margin:0 0 18px}.play-button{background:linear-gradient(135deg,#f3c45f,#df9f36);color:#20180b;border:0;border-radius:3px;padding:13px 19px;font:700 10px 'DM Mono';letter-spacing:1px;box-shadow:0 5px 25px #e6ae3b33;cursor:pointer;transition:transform .15s,filter .15s}.play-button:hover{transform:translateY(-2px);filter:brightness(1.08)}.play-button span{font-size:11px;margin-right:8px}.key-guide{margin-top:17px;display:fl