-gold);border:0;border-radius:3px;padding:9px;cursor:pointer}.hit-feedback{position:absolute;z-index:3;top:34%;left:0;right:0;text-align:center;font:italic 700 22px 'Playfair Display';color:var(--gold);text-shadow:0 2px 8px #000;pointer-events:none;opacity:0;transform:scale(.8);transition:opacity .12s,transform .12s}.hit-feedback.show{opacity:1;transform:scale(1)}.stage-footer{display:flex;justify-content:space-between;align-items:center;height:39px;color:#888477;font-size:8px}.audience{display:flex;align-items:center;gap:9px}.audience span{color:#e4b850;font-size:14px}.pause-help{display:flex;align-items:center;gap:6px}.pause-help kbd{font:8px 'DM Mono';border:1px solid #47443b;border-radius:2px;padding:3px 5px;color:#c1baa9}.pause-help span{margin:0 4px;color:#555}.stat-card,.controls-card,.setlist-card{padding:14px}.stat-card>.eyebrow,.controls-card>.eyebrow,.setlist-card>.eyebrow{margin-bottom:13px}.accuracy-ring{width:100px;height:100px;border-radius:50%;margin:2px auto 15px;display:grid;place-items:center;background:conic-gradient(var(--gold) 0%,#39372f 0);position:relative}.accuracy-ring:before{content:'';position:absolute;inset:5px;border-radius:50%;background:#191916}.accuracy-ring>div{z-index:1;text-align:center}.accuracy-ring strong{display:block;font:500 24px 'DM Mono';color:#f4e3b4}.accuracy-ring small{font:8px 'DM Mono';color:#aaa494;letter-spacing:.6px}.stat-line{display:flex;justify-content:space-between;padding:9px 0;border-top:1px solid #ffffff0f;color:#a09a8d;font-size:8px}.stat-line b{color:#e6dfce;font-weight:400}.best-line b{color:var(--gold)}.controls-card{color:#aaa494}.control-row{display:flex;align-items:center;gap:8px;margin:10px 0}.control-row p{font:9px/1.45 'DM Sans';margin:0;color:#c0bbaf}.mini-keys{display:flex;gap:2px;flex-shrink:0}.mini-keys i{font-style:normal;padding:4px 5px;min-width:auto;font-size:8px}.space-key{flex:0 0 47px;text-align:center;font-size:7px;border:1px solid #625841;color:#e3c57c;border-radius:2px;padding:5px 2px